#include<iostream>
#include<cstdio>
#include<cstring>
#include<algorithm>
using namespace std;

int n, k, p;

int power_mod(int base, int exp) {
    int result = 1;
    int current = base;
    while (exp > 0) {
        if (exp & 1) result = (long long)result * current % p;
        current = (long long)current * current % p;
        exp >>= 1;
    }
    return result;
}

int get_lowbit(int x) {
    return x & (-x);
}

int memo_table[30][250005];
int fact_arr[250005], inv_fact_arr[250005];

void prepare_factorials() {
    fact_arr[0] = 1;
    for (int i = 1; i <= n; i++)
        fact_arr[i] = (long long)fact_arr[i - 1] * i % p;
    inv_fact_arr[n] = power_mod(fact_arr[n], p - 2);
    for (int i = n; i >= 1; i--)
        inv_fact_arr[i - 1] = (long long)inv_fact_arr[i] * i % p;
}

int recursive(int idx, int mask) {
    if (memo_table[idx][mask] != -1)
        return memo_table[idx][mask];
    if (mask == 0) {
        int res = fact_arr[n];
        for (int i = 1; i <= idx; i++)
            res = (long long)res * (k - i + 1) % p;
        return memo_table[idx][mask] = res;
    }
    int total = 0;
    int rem = mask - get_lowbit(mask);
    for (int subset = rem; subset; subset = (subset - 1) & rem)
        total = (total + (long long)inv_fact_arr[mask - subset] * recursive(idx + 1, subset)) % p;
    total = (total + (long long)inv_fact_arr[mask] * recursive(idx + 1, 0)) % p;
    return memo_table[idx][mask] = total;
}

int main() {
    scanf("%d %d %d", &n, &k, &p);
    int ans = 1;
    for (int i = 1; i <= n; i++)
        ans = (long long)ans * k % p;
    if (n % 2 == 0) {
        memset(memo_table, -1, sizeof(memo_table));
        prepare_factorials();
        ans = (ans - recursive(0, n) + p) % p;
    }
    printf("%d\n", ans);
    return 0;
}
